// The per-property C++ calls generated by //tools/style-codegen
// (generated.cpp), and the canonical-text helpers they share with
// reference.cpp.

#pragma once

#include <mln/renderer/cross_faded_property_evaluator.hpp>
#include <mln/renderer/possibly_evaluated_property_value.hpp>
#include <mln/style/conversion_impl.hpp>
#include <mln/style/layer.hpp>
#include <mln/style/style_property.hpp>
#include <mln/util/feature.hpp>

#include <memory>
#include <optional>
#include <string>

namespace codegen_difftest {

// `std::make_unique<XLayer>("layer"[, "source"])` for a layer type.
std::unique_ptr<mln::style::Layer> makeLayer(const std::string& type);

// `makeStyleProperty(XLayer::getDefaultYyy())`.
std::optional<mln::style::StyleProperty> layerDefault(const std::string& type, const std::string& name);

// `makeValue(Light::getDefaultYyy())`.
std::optional<mln::Value> lightDefault(const std::string& name);

// The layer's paint (`untransitioned().evaluate(parameters)`) and layout
// (`evaluate(parameters)`) properties at `zoom`, "name=value;" per property.
std::string evaluateLayer(const mln::style::Layer& layer, float zoom);

// Defined in reference.cpp.
std::string canonical(const mln::Value& value);

// One possibly-evaluated value, by kind.
template <class T>
std::string pe(const T& t) {
    return canonical(mln::style::conversion::makeValue(t));
}

template <class T>
std::string pe(const mln::Faded<T>& faded) {
    return "faded(" + pe(faded.from) + "," + pe(faded.to) + ")";
}

template <class T>
std::string pe(const mln::PossiblyEvaluatedPropertyValue<T>& value) {
    return value.match([](const T& t) { return "c:" + pe(t); },
                       [](const mln::style::PropertyExpression<T>& e) {
                           return "e:" + canonical(e.getExpression().serialize());
                       });
}

template <class T>
std::string pe(const mln::PossiblyEvaluatedPropertyValue<mln::Faded<T>>& value) {
    return value.match([](const mln::Faded<T>& t) { return "c:" + pe(t); },
                       [](const mln::style::PropertyExpression<T>& e) {
                           return "e:" + canonical(e.getExpression().serialize());
                       });
}

} // namespace codegen_difftest
